dslRule:
/*!
@id: change.method.visibility.privateToProtected
@description: Changes a method's visibility from private to protected.
@tags: visibility, access-modifier
*/
private $ReturnType $methodName($params$)
=>
protected $ReturnType $methodName($params$)
;;

beforeExample:
package org.eclipse.jdt.internal.ui.text.template.contentassist;

import java.util.ArrayList;
import org.eclipse.jdt.internal.ui.JavaPluginImages;
import org.eclipse.jdt.internal.ui.text.template.JavaContextType;
import org.eclipse.jdt.internal.ui.text.template.SWTContextType;
import org.eclipse.jface.text.templates.TemplateContextType;
import org.eclipse.jface.text.templates.TemplateProposal;
import org.eclipse.swt.graphics.Image;

public class TemplateEngine {
    private TemplateContextType fContextType;
    private ArrayList<TemplateProposal> fProposals;

    private TemplateContextType getContextType() {
        return fContextType;
    }

    private ArrayList<TemplateProposal> getProposals() {
        return fProposals;
    }

    private Image getImage() {
        if (fContextType instanceof SWTContextType)
            return JavaPluginImages.get(JavaPluginImages.IMG_OBJS_SWT_TEMPLATE);
        else
            return JavaPluginImages.get(JavaPluginImages.IMG_OBJS_TEMPLATE);
    }

    public void someOtherMethod() { }
}

