negativeExample:
package org.eclipse.jdt.internal.ui.text.template.contentassist;

import java.util.ArrayList;
import org.eclipse.jface.text.templates.TemplateProposal;

public class AnotherClass {

    // Should not match public method
    public String getPublicString() {
        return "hello";
    }

    // Should not match static private method
    private static int calculateValue() {
        return 10;
    }

    // Should not match a protected method (already protected)
    protected ArrayList<TemplateProposal> getProtectedProposals() {
        return new ArrayList<>();
    }

    // Should not match a method with a different modifier (e.g., package-private)
    String getPackagePrivateString() {
        return "package";
    }
}
